import { Component, ComponentInterface, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { ValueFieldGroup, ValueFieldInputSize } from '../types';
import { Vue2ValueFix } from '@src/framework/decorators';
import { CSSProperties, formatCSSLength } from '@src/shared/dom';

const prefix = 'value-field__grouped';

/**
 * @part input - The native input element.
 */
@Component({
  tag: 'ks-grouped-value-field',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsGroupedValueField implements ComponentInterface {
  @Element() el!: HTMLKsGroupedValueFieldElement;
  contentEl!: HTMLDivElement;

  /** Render value */
  @Prop() @Vue2ValueFix() value: ValueFieldGroup[] = [];

  /** Size of the tag. */
  @Prop() size?: ValueFieldInputSize;

  /** Whether to show close button of tags. */
  @Prop() closeable = true;

  /** Whether the fields presenter is disabled. If `true`, interaction is not allowed. */
  @Prop() disabled?: boolean;

  /** The height of the value field. */
  @Prop() valueFieldHeight: string | number | { min?: string | number; max?: string | number } = { max: 192 };

  /**
   * @private
   * The inline-end offset reserved for the suffix area.
   */
  @Prop() suffixOffset = 0;

  /** Placeholder of the input field. */
  @Prop() placeholder?: string;

  /** Emitted when the close button of tag is clicked. */
  @Event({ bubbles: false, composed: false }) ksTagClose!: EventEmitter<{
    groupValue: string | number;
    value: string | number;
  }>;

  get containerStyle() {
    const scrollbarStyle: CSSProperties = {
      paddingInlineEnd: formatCSSLength(this.suffixOffset),
    };
    if (typeof this.valueFieldHeight === 'object') {
      scrollbarStyle['minHeight'] = formatCSSLength(this.valueFieldHeight.min);
      scrollbarStyle['maxHeight'] = formatCSSLength(this.valueFieldHeight.max);
    } else {
      scrollbarStyle['height'] = formatCSSLength(this.valueFieldHeight);
    }
    return scrollbarStyle;
  }

  private renderGroupedItem(item: ValueFieldGroup) {
    return (
      <div class={`${prefix}__item`}>
        {typeof item.label === 'string' && (
          <div
            class={{
              [`${prefix}__item-label`]: true,
              [`${prefix}__item-label--disabled`]: this.disabled || item.disabled || false,
            }}
          >
            {item.label}
          </div>
        )}
        <div class={`${prefix}__item-content`}>
          {item.children.map((child) => (
            <ks-tag
              key={child.value}
              size={this.size}
              closeable={this.closeable && (child.closeable === undefined ? true : child.closeable)}
              variant={child.status === 'default' ? 'neutral' : child.status}
              disabled={this.disabled || item.disabled || child.disabled}
              onKsClose={() => {
                this.ksTagClose.emit({
                  groupValue: item.value,
                  value: child.value,
                });
              }}
              data-testid={`grouped-index-iybDhK-${child.value}`}
            >
              {child.label}
            </ks-tag>
          ))}
        </div>
      </div>
    );
  }

  render() {
    return (
      <Host class="KsGroupedValueField">
        <div
          ref={(el) => (this.contentEl = el!)}
          class={{
            [prefix]: true,
            [`${prefix}--scroll`]: true,
          }}
          style={this.containerStyle}
        >
          {this.value.map((item) => this.renderGroupedItem(item))}
          <input
            class={{
              [`${prefix}__input--hidden`]: this.value.length > 0,
            }}
            part="input"
            type="text"
            placeholder={this.value.length === 0 ? this.placeholder : ''}
            disabled={this.disabled}
            readOnly
          />
        </div>
      </Host>
    );
  }
}
